 bool populate_roles_caches(THD *thd, TABLE_LIST * tablelst);
diff --git a/sql/auth/sql_authorization.cc b/sql/auth/sql_authorization.cc
index 59819ccb986d..a847303056c3 100644
--- a/sql/auth/sql_authorization.cc
+++ b/sql/auth/sql_authorization.cc
@@ -2388,7 +2388,7 @@ int mysql_table_grant(THD *thd, TABLE_LIST *table_list,
     }

     if (set_and_validate_user_attributes(thd, Str, what_to_set,
-                                         is_privileged_user))
+                                         is_privileged_user, false))
     {
       result= true;
       continue;
@@ -2605,7 +2605,7 @@ bool mysql_routine_grant(THD *thd, TABLE_LIST *table_list, bool is_proc,
     }

     if (set_and_validate_user_attributes(thd, Str, what_to_set,
-                                         is_privileged_user))
+                                         is_privileged_user, false))
     {
       result= true;
       continue;
@@ -2969,7 +2969,7 @@ bool mysql_grant(THD *thd, const char *db, List <LEX_USER> &list,
     }

     if (set_and_validate_user_attributes(thd, Str, what_to_set,
-                                         is_privileged_user))
+                                         is_privileged_user, false))
     {
       result= true;
